package com.ella.infoboxinventorycount;

import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.InfoBoxMenuClicked;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

@Slf4j
@PluginDescriptor(name = "Infobox Inventory Count", description = "Shift-click an inventory item to pin a live "
		+ "count of it as a sidebar infobox; shift-click the infobox to remove it", tags = { "infobox", "inventory",
				"count", "counter", "tracker" })
public class InfoboxInventoryCountPlugin extends Plugin
{
	private static final String CONFIG_GROUP = "infoboxinventorycount";
	private static final String CONFIG_KEY_TRACKED_ITEMS = "trackedItems";

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientThread clientThread;

	private final Map<Integer, ItemCounter> counters = new HashMap<>();

	@Override
	protected void startUp()
	{
		String csv = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY_TRACKED_ITEMS);
		if (csv == null || csv.isEmpty())
		{
			return;
		}

		// startUp() runs on the Swing EDT (e.g. when the plugin is toggled on from the config
		// panel), but addCounter() reads item definitions via ItemManager, which asserts it's
		// called on the client thread.
		clientThread.invoke(() ->
		{
			for (String part : csv.split(","))
			{
				try
				{
					addCounter(Integer.parseInt(part.trim()));
				}
				catch (NumberFormatException e)
				{
					log.warn("Ignoring invalid tracked item id '{}'", part);
				}
			}
		});
	}

	@Override
	protected void shutDown()
	{
		counters.values().forEach(infoBoxManager::removeInfoBox);
		counters.clear();
	}

	/**
	 * While Shift is held, adds an "Add infobox counter" entry to an inventory item's
	 * context menu (next to Examine), letting the item be pinned as a live count infobox.
	 */
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		MenuEntry[] entries = event.getMenuEntries();
		for (int idx = entries.length - 1; idx >= 0; --idx)
		{
			MenuEntry entry = entries[idx];
			Widget w = entry.getWidget();

			if (w == null || WidgetUtil.componentToInterface(w.getId()) != InterfaceID.INVENTORY
					|| !"Examine".equals(entry.getOption()) || entry.getIdentifier() != 10)
			{
				continue;
			}

			int itemId = w.getItemId();
			if (counters.containsKey(itemId))
			{
				continue;
			}

			client.getMenu().createMenuEntry(idx).setOption("Add infobox counter").setTarget(entry.getTarget())
					.setType(MenuAction.RUNELITE).onClick(e -> addCounter(itemId));
		}
	}

	/**
	 * Every tick, add or remove the "Remove" option on each of our infoboxes depending on
	 * whether Shift is currently held, so shift-clicking an infobox is what surfaces it.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (counters.isEmpty())
		{
			return;
		}

		boolean shiftHeld = client.isKeyPressed(KeyCode.KC_SHIFT);
		for (ItemCounter counter : counters.values())
		{
			OverlayMenuEntry removeEntry = removeMenuEntryFor(counter);
			boolean hasRemoveEntry = counter.getMenuEntries().contains(removeEntry);
			if (shiftHeld && !hasRemoveEntry)
			{
				counter.getMenuEntries().add(removeEntry);
			}
			else if (!shiftHeld && hasRemoveEntry)
			{
				counter.getMenuEntries().remove(removeEntry);
			}
		}
	}

	@Subscribe
	public void onInfoBoxMenuClicked(InfoBoxMenuClicked event)
	{
		if (!(event.getInfoBox() instanceof ItemCounter))
		{
			return;
		}

		ItemCounter counter = (ItemCounter) event.getInfoBox();
		if (!removeMenuEntryFor(counter).equals(event.getEntry()))
		{
			return;
		}

		removeCounter(counter.getItemId());
	}

	private static OverlayMenuEntry removeMenuEntryFor(ItemCounter counter)
	{
		return new OverlayMenuEntry(MenuAction.RUNELITE_INFOBOX, "Remove Count", counter.getItemName());
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (counters.isEmpty() || event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		Map<Integer, Integer> counts = new HashMap<>();
		for (Item item : event.getItemContainer().getItems())
		{
			counts.merge(item.getId(), item.getQuantity(), Integer::sum);
		}

		for (Map.Entry<Integer, ItemCounter> entry : counters.entrySet())
		{
			entry.getValue().setCount(counts.getOrDefault(entry.getKey(), 0));
		}
	}

	private void addCounter(int itemId)
	{
		if (counters.containsKey(itemId))
		{
			return;
		}

		ItemComposition composition = itemManager.getItemComposition(itemId);
		ItemCounter counter = new ItemCounter(itemManager.getImage(itemId), this, itemId, composition.getName(),
				computeCount(itemId));
		counter.setTooltip(composition.getName());

		infoBoxManager.addInfoBox(counter);
		counters.put(itemId, counter);
		persistTrackedItems();
	}

	private void removeCounter(int itemId)
	{
		ItemCounter counter = counters.remove(itemId);
		if (counter == null)
		{
			return;
		}

		infoBoxManager.removeInfoBox(counter);
		persistTrackedItems();
	}

	private int computeCount(int itemId)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return 0;
		}

		int count = 0;
		for (Item item : inventory.getItems())
		{
			if (item.getId() == itemId)
			{
				count += item.getQuantity();
			}
		}

		return count;
	}

	private void persistTrackedItems()
	{
		if (counters.isEmpty())
		{
			configManager.unsetConfiguration(CONFIG_GROUP, CONFIG_KEY_TRACKED_ITEMS);
			return;
		}

		String csv = counters.keySet().stream().map(String::valueOf).collect(Collectors.joining(","));
		configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY_TRACKED_ITEMS, csv);
	}
}

package com.ella.infoboxinventorycount;

import java.awt.image.BufferedImage;
import lombok.Getter;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.Counter;

class ItemCounter extends Counter
{
	@Getter
	private final int itemId;

	@Getter
	private final String itemName;

	ItemCounter(BufferedImage image, Plugin plugin, int itemId, String itemName, int count)
	{
		super(image, plugin, count);
		this.itemId = itemId;
		this.itemName = itemName;
	}
}

package com.ella.infoboxinventorycount;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class InfoboxInventoryCountPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(InfoboxInventoryCountPlugin.class);
		RuneLite.main(args);
	}
}
